import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test("extraction completes in the background", { tag: "@DOC-02" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const vendorRes = await member.post("/api/vendors", {
    data: {
      name: uniqueName("DOC-02 Vendor"),
      category: "services",
      contact_email: `doc02.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@vendor-intake.com`,
    },
  });
  expect(vendorRes.status(), await vendorRes.text()).toBe(201);
  const vendor = await vendorRes.json();
  expect(vendor.status).toBe("draft");

  // Act
  const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "insurance_certificate",
      file: {
        name: "insurance_certificate.txt",
        mimeType: "text/plain",
        buffer: readFileSync(sample("insurance_certificate.txt")),
      },
    },
  });
  expect(uploadRes.status(), await uploadRes.text()).toBe(201);
  const uploaded = await uploadRes.json();
  expect(uploaded.kind).toBe("insurance_certificate");

  // Assert: processing finishes in the background
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/documents/${uploaded.id}`);
        expect(res.status(), await res.text()).toBe(200);
        return (await res.json()).status as string;
      },
      { timeout: 60_000, intervals: [500, 1000, 2000] },
    )
    .not.toBe("processing");

  const docRes = await member.get(`/api/documents/${uploaded.id}`);
  expect(docRes.status(), await docRes.text()).toBe(200);
  const document = await docRes.json();
  expect(document.status, JSON.stringify(document)).toBe("extracted");

  const extractionRes = await member.get(`/api/documents/${uploaded.id}/extraction`);
  expect(extractionRes.status(), await extractionRes.text()).toBe(200);
  const extraction = await extractionRes.json();

  for (const field of ["insurer", "policy_number", "coverage_amount", "expiry_date"]) {
    expect(extraction.fields, `missing field ${field}: ${JSON.stringify(extraction)}`).toHaveProperty([field]);
  }

  for (const [name, field] of Object.entries(extraction.fields as Record<string, { confidence: number }>)) {
    expect(typeof field.confidence, `confidence type for ${name}`).toBe("number");
    expect(field.confidence, `confidence for ${name}`).toBeGreaterThanOrEqual(0);
    expect(field.confidence, `confidence for ${name}`).toBeLessThanOrEqual(1);
  }
});
